                coords[i] = v

    raw_demands = get_any(instance, ["demands", "loads"], None)
    if not demand and raw_demands is not None:
        if isinstance(raw_demands, dict):
            demand.update(raw_demands)
        elif isinstance(raw_demands, list):
            for i, v in enumerate(raw_demands):
                demand[i] = v

    if capacity is None:
        if isinstance(instance, dict):
            for k in ["capacity", "vehicle_capacity", "cap"]:
                if k in instance and is_num(instance[k]):
                    capacity = instance[k]
                    break
    if capacity is None:
        capacity = 10 ** 18

    ids = set(coords.keys()) | set(demand.keys())
    if depot in ids:
        ids.remove(depot)
    customers = list(ids)
    if not customers:
        return []

    for cid in customers:
        if cid not in demand:
            demand[cid] = 0

    def dist(a, b):
        ca = coords.get(a)
        cb = coords.get(b)
        if ca is None or cb is None:
            return 0.0 if a == b else 1.0
        dx = ca[0] - cb[0]
        dy = ca[1] - cb[1]
        return (dx * dx + dy * dy) ** 0.5

    has_depot_coords = depot in coords
    if has_depot_coords:
        dx0, dy0 = coords[depot][0], coords[depot][1]

        def angle_key(cid):
            x = coords[cid][0] - dx0
            y = coords[cid][1] - dy0
            if x >= 0 and y >= 0:
                quad = 0
            elif x < 0 and y >= 0:
                quad = 1
            elif x < 0 and y < 0:
                quad = 2
            else:
                quad = 3
            slope = y / x if x != 0 else (10 ** 18 if y >= 0 else -10 ** 18)
            return (quad, slope, demand.get(cid, 0), cid)

        customers.sort(key=angle_key)
    else:
        customers.sort(key=lambda c: (demand.get(c, 0), c))

    # Constructive sweep with nearest feasible seed.
    routes = []
    unserved = customers[:]

    while unserved:
        seed = None
        best_key = None
        for cid in unserved:
            d = demand.get(cid, 0)
            if d <= capacity:
                k = (dist(depot, cid), -d, cid)
                if seed is None or k < best_key:
                    seed = cid
                    best_key = k
        if seed is None:
            seed = unserved[0]
        route = [seed]
        load = demand.get(seed, 0)
        unserved.remove(seed)
        current = seed

        while True:
            best = None
            best_key = None
            for cid in unserved:
                d = demand.get(cid, 0)
                if load + d > capacity:
                    continue
                k = (dist(current, cid), dist(depot, cid), -d, cid)
                if best is None or k < best_key:
                    best = cid
                    best_key = k
            if best is None:
                break
            route.append(best)
            load += demand.get(best, 0)
            unserved.remove(best)
            current = best
        routes.append(route)

    def route_load(route):
        s = 0
        for c in route:
            s += demand.get(c, 0)
        return s

    def route_cost(route):
        if not route:
            return 0.0
        c = dist(depot, route[0]) + dist(route[-1], depot)
        for i in range(len(route) - 1):
            c += dist(route[i], route[i + 1])
        return c

    def total_cost(rs):
        t = 0.0
        for r in rs:
            t += route_cost(r)
        return t

    # Repair/merge pass: try to concatenate routes if capacity permits and it helps.
    improved = True
    while improved:
        improved = False
        i = 0
        while i < len(routes):
            j = i + 1
            while j < len(routes):
                ri, rj = routes[i], routes[j]
                if route_load(ri) + route_load(rj) <= capacity:
                    merged = ri + rj
                    if route_cost(merged) <= route_cost(ri) + route_cost(rj):
                        routes[i] = merged
                        routes.pop(j)
                        improved = True
                        continue
                j += 1
            i += 1

    # Local search: intra-route 2-opt, inter-route relocate and swap.
    def two_opt(route):
        if len(route) < 4:
            return route
        best = route[:]
        best_cost = route_cost(best)
        changed = True
        while changed:
            changed = False
            n = len(best)
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    cand = best[:i + 1] + best[i + 1:j + 1][::-1] + best[j + 1:]
                    c = route_cost(cand)
                    if c + 1e-12 < best_cost:
                        best = cand
                        best_cost = c
                        changed = True
                        break
                if changed:
                    break
        return best

    for idx in range(len(routes)):
        routes[idx] = two_opt(routes[idx])

    def try_relocate():
        for a in range(len(routes)):
            for b in range(len(routes)):
                if a == b:
                    continue
                ra = routes[a]
                rb = routes[b]
                la = route_load(ra)
                lb = route_load(rb)
                for i, node in enumerate(ra):
                    dn = demand.get(node, 0)
                    if lb + dn > capacity:
                        continue
                    ra_wo = ra[:i] + ra[i + 1:]
                    base_a = route_cost(ra) + route_cost(rb)
                    for pos in range(len(rb) + 1):
                        nb = rb[:pos] + [node] + rb[pos:]
                        na = ra_wo
                        new_cost = route_cost(na) + route_cost(nb)
                        if new_cost + 1e-12 < base_a:
                            routes[a] = na
                            routes[b] = nb
                            return True
        return False

    def try_swap():
        for a in range(len(routes)):
            for b in range(a + 1, len(routes)):
                ra = routes[a]
                rb = routes[b]
                la = route_load(ra)
                lb = route_load(rb)
                base = route_cost(ra) + route_cost(rb)
                for i, na in enumerate(ra):
                    da = demand.get(na, 0)
                    for j, nb in enumerate(rb):
                        db = demand.get(nb, 0)
                        if la - da + db > capacity:
                            continue
                        if lb - db + da > capacity:
                            continue
                        ca = ra[:i] + [nb] + ra[i + 1:]
                        cb = rb[:j] + [na] + rb[j + 1:]
                        new_cost = route_cost(ca) + route_cost(cb)
                        if new_cost + 1e-12 < base:
                            routes[a] = ca
                            routes[b] = cb
                            return True
        return False

    # Limited deterministic improvement loop.
    for _ in range(3):
        changed = False
        for i in range(len(routes)):
            new_r = two_opt(routes[i])
            if route_cost(new_r) + 1e-12 < route_cost(routes[i]):
                routes[i] = new_r
                changed = True
        if try_relocate():
            changed = True
        if try_swap():
            changed = True
        if not changed:
            break

    # Final cleanup: remove empty routes if any.
    routes = [r for r in routes if r]
    return routes
